function replaceIcons(text) {
  if (!text) return "";
  let html = text;
  Object.keys(ICON_MAP).forEach(tag => {
    const iconFile = ICON_MAP[tag];
    const safeTag = tag.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(safeTag, 'g');
    html = html.replace(regex, `<img src="${iconFile}" class="inline-icon" alt="icon">`);
  });
  return html;
}

function hasPrintableFile(model) {
  if (!model) return false;
  if (model.print !== undefined && model.print !== null) {
    if (typeof model.print === "string") {
      return model.print.toLowerCase() === "yes" || model.print.toLowerCase() === "true";
    }
    return Boolean(model.print);
  }
  const printableIdentityKey = `${model.name || ""}||${model.realname || ""}||${model.base || ""}`;
  const imageFile = typeof model.img === "string" ? model.img.split('/').pop() : "";
  return printableModelKeys.has(printableIdentityKey)
    || printableModelImageKeys.has(imageFile)
    || printableModelNames.has(model.name);
}

function getPrintableStatusText(model) {
  return `Print - ${hasPrintableFile(model) ? "yes" : "no"}`;
}

