function t(key, params = {}) {
  const lang = translations[currentLang] || translations.ru;
  let text = lang[key] || translations.ru[key] || key;
  for (const [param, value] of Object.entries(params)) {
    text = text.replace(new RegExp(`\\{${param}\\}`, 'g'), value);
  }
  return text;
}

function getI18nNodeCache() {
  if (!i18nNodeCache) {
    i18nNodeCache = {
      langButtons: Array.from(document.querySelectorAll('.lang-btn')),
      textNodes: Array.from(document.querySelectorAll('[data-i18n]')),
      titleNodes: Array.from(document.querySelectorAll('[data-i18n-title]')),
      placeholderNodes: Array.from(document.querySelectorAll('[data-i18n-placeholder]'))
    };
  }

  return i18nNodeCache;
}

function setLanguage(lang) {
  if (!translations[lang]) return;
  currentLang = lang;
  const uiNodes = getI18nNodeCache();

  // Обновляем кнопки переключения
  uiNodes.langButtons.forEach(btn => {
    btn.classList.toggle('active', btn.dataset.lang === lang);
  });

  // Обновляем текстовые элементы (innerHTML для поддержки HTML тегов)
  uiNodes.textNodes.forEach(el => {
    const key = el.dataset.i18n;
    el.innerHTML = t(key);
  });

  // Обновляем title атрибуты
  uiNodes.titleNodes.forEach(el => {
    const key = el.dataset.i18nTitle;
    el.title = t(key);
  });

  // Обновляем placeholder'ы
  uiNodes.placeholderNodes.forEach(el => {
    const key = el.dataset.i18nPlaceholder;
    el.placeholder = t(key);
  });

  // Сохраняем в localStorage
  localStorage.setItem('bmg_lang', lang);

  const compendiumModal = document.getElementById('compendiumModal');
  const compendiumOpen = compendiumModal?.classList.contains('active');
  const modelSearchOpen = document.getElementById('modelSearchModal')?.classList.contains('active');
  const rulesSearchOpen = modelSearchOpen && modelSearchMode === "rules";

  if (compendiumOpen || rulesSearchOpen) {
    rebuildCompendiumHTML();
  }

  if (compendiumOpen) {
    const query = $("compendiumSearch")?.value || "";
    updateCompendiumSearchUi();
    renderCompendiumUnifiedSearch(query);
  }

  if (modelSearchOpen) {
    updateModelSearchUi();
    renderUnifiedSearch();
  }

  if (document.getElementById('fullCard')?.classList.contains('active')) {
    rerenderOpenFullCard();
  }

  if (currentMode === 'my-crews') {
    renderMyCrews();
  }
}

