function uiText(key) {
  return (localizedUi[currentLang] && localizedUi[currentLang][key]) || localizedUi.en[key] || key;
}

const normalizedExactDictionaryCache = new WeakMap();

function normalizeExactKey(text) {
  return String(text)
    .replace(/[’`]/g, "'")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function translateExact(text, dictionary) {
  if (!text) return text;
  const langDict = dictionary[currentLang] || {};
  if (langDict[text]) return langDict[text];

  let normalizedDict = normalizedExactDictionaryCache.get(langDict);
  if (!normalizedDict) {
    normalizedDict = {};
    Object.entries(langDict).forEach(([key, value]) => {
      normalizedDict[normalizeExactKey(key)] = value;
    });
    normalizedExactDictionaryCache.set(langDict, normalizedDict);
  }

  return normalizedDict[normalizeExactKey(text)] || text;
}

function escapeRegExp(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function translateWithGlossary(text, glossary) {
  if (!text || currentLang === "en") return text;

  let result = String(text);
  const langGlossary = glossary[currentLang] || {};
  const keys = Object.keys(langGlossary).sort((a, b) => b.length - a.length);

  keys.forEach(key => {
    const value = langGlossary[key];
    const pattern = new RegExp(`(^|[\\s(\\-/'"])${escapeRegExp(key)}(?=$|[\\s)\\-/'",.!?])`, "g");
    result = result.replace(pattern, (match, prefix) => `${prefix}${value}`);
  });

  return result;
}

function postProcessLocalizedText(text) {
  if (!text || currentLang === "en") return text;

  let result = String(text);
  result = translateProseText(result);
  result = result.replace(/Suspect маркер\s+(?:маркер|marker)(?=$|[\s.,!?;:")\]])/g, "Suspect маркер");
  result = result.replace(/Suspect маркеры\s+(?:маркеры|markers)(?=$|[\s.,!?;:")\]])/g, "Suspect маркеры");

  Object.entries(rankLabels).forEach(([rank, labels]) => {
    result = result.replace(new RegExp(`\\b${escapeRegExp(rank)}\\b`, "g"), labels[currentLang] || labels.en || rank);
  });

  Object.entries(factionLabels).forEach(([faction, labels]) => {
    result = result.replace(new RegExp(escapeRegExp(faction), "g"), labels[currentLang] || labels.en || faction);
  });

  return result;
}

function postProcessLocalizedDisplay(text) {
  if (!text || currentLang === "en") return text;

  let result = String(text);
  result = translateWithGlossary(result, displayGlossary);
  return postProcessLocalizedText(result);
}

function localizeFactionName(name) {
  const entry = factionLabels[name];
  return entry ? (entry[currentLang] || entry.en || name) : name;
}

function localizeFactionList(input) {
  const values = Array.isArray(input) ? input : String(input || "").split(/\s*[\/,]\s*/).filter(Boolean);
  return values.map(localizeFactionName).join(" • ");
}

