  result = result.replace(/Model has ([^.]+?) trait$/g, (_, value) => `Модель имеет трейт ${translateDisplayText(value)}`);
  result = result.replace(/Model has ([^.]+?) trait\./g, (_, value) => `Модель имеет трейт ${translateDisplayText(value)}.`);
  result = result.replace(/Model has ([^.]+?) rule$/g, (_, value) => `Модель имеет правило ${translateDisplayText(value)}`);
  result = result.replace(/Model has ([^.]+?) rule\./g, (_, value) => `Модель имеет правило ${translateDisplayText(value)}.`);
  result = result.replace(/Only ([^.]+?) can purchase this equipment\./g, (_, value) => `Только ${translateDisplayText(value)} могут покупать это снаряжение.`);
  result = result.replace(/([^.]+?) cannot purchase this equipment\./g, (_, value) => `${translateDisplayText(value)} не могут покупать это снаряжение.`);
  result = result.replace(/Alias: ([^.]+?) in crew/g, (_, value) => `Alias: ${translateDisplayText(value)} в команде`);
