  result = result.replace(/Damage marker/g, "маркер урона");
  result = result.replace(/Damage markers/g, "маркеры урона");
  result = result.replace(/movement action/g, "действие перемещения");
  result = result.replace(/Task token/g, "маркер задачи");
  result = result.replace(/Prepare the Game/g, "подготовка игры");
  result = result.replace(/ranged weapon/g, "дальнобойное оружие");
  result = result.replace(/ranged weapons/g, "дальнобойное оружие");
  result = result.replace(/Melee Attack/g, "атака ближнего боя");
