  result = result.replace(/When this model is included in your crew/g, "Когда эта модель включена в вашу команду");
  result = result.replace(/At the beginning of the Raise the Plan phase/g, "В начале фазы Raise the Plan");
  result = result.replace(/for the remainder of the activation/g, "до конца активации");
  result = result.replace(/for the rest of the round/g, "до конца раунда");
  result = result.replace(/for the purposes of forming the crew/g, "для целей формирования команды");
  result = result.replace(/for the duration of the attack/g, "на время этой атаки");
  result = result.replace(/ignore the penalty for move before attacking/g, "игнорировать штраф за движение перед атакой");
