function localizeCompendiumTitle(title) {
  return translateDisplayText(title);
}

function localizeCompendiumBody(text) {
  const exactTranslation = translateExact(text, exactCompendiumBodyTranslations);
  if (exactTranslation !== text) return postProcessLocalizedText(exactTranslation);

  const normalizedText = normalizeTranslationKey(text);
  const normalizedTranslation = (normalizedCompendiumBodyTranslations[currentLang] || {})[normalizedText];
  if (normalizedTranslation) return postProcessLocalizedText(normalizedTranslation);

  const fallbackTranslation = (normalizedCompendiumBodyFallbacks[currentLang] || {})[normalizedText];
  if (fallbackTranslation) return postProcessLocalizedText(fallbackTranslation);

  return postProcessLocalizedText(translateSentence(text));
}

function getCompendiumCache(lang = currentLang, force = false) {
  if (!window.compendium) {
    return { entries: [], keys: [], html: "" };
  }

  if (!force && compendiumCacheByLang[lang]) {
    return compendiumCacheByLang[lang];
  }

  const previousLang = currentLang;
  currentLang = lang;

  try {
    const entries = Object.keys(window.compendium).map(key => {
      const localizedTitle = localizeCompendiumTitle(key);
      const localizedBody = localizeCompendiumBody(compendium[key] || "");

      return {
        key,
        keyLower: key.toLowerCase(),
        localizedTitle,
        localizedTitleLower: localizedTitle.toLowerCase(),
        localizedBody,
        localizedBodyLower: localizedBody.toLowerCase(),
        html: `
      <div class="comp-entry">
        <div class="comp-title">${replaceIcons(localizedTitle)}</div>
        <div class="comp-text">${replaceIcons(localizedBody.replace(/\n/g, "<br>"))}</div>
      </div>`
      };
    }).sort((a, b) => a.localizedTitleLower.localeCompare(b.localizedTitleLower));

    const cache = {
      entries,
      keys: entries.map(entry => entry.key),
      html: entries.map(entry => entry.html).join("")
    };

    compendiumCacheByLang[lang] = cache;
    return cache;
  } finally {
    currentLang = previousLang;
  }
}

function rebuildCompendiumHTML(force = false) {
  const cache = getCompendiumCache(currentLang, force);
  compendiumKeys = cache.keys;
  allCompendiumHTML = cache.html;

  if ($("compendiumList")) {
    $("compendiumList").innerHTML = cache.html;
  }

  return cache;
}

function renderCompendiumSearchResults(query = "") {
  const cache = rebuildCompendiumHTML();
  const normalizedQuery = String(query).toLowerCase().trim();

  if (!normalizedQuery) {
    $("compendiumList").innerHTML = cache.html;
    return;
  }

  const html = cache.entries
    .filter(entry =>
      entry.keyLower.includes(normalizedQuery) ||
      entry.localizedTitleLower.includes(normalizedQuery) ||
      entry.localizedBodyLower.includes(normalizedQuery)
    )
    .map(entry => entry.html)
    .join("");

  $("compendiumList").innerHTML = html || `<div style="text-align:center;color:#888;padding:80px;font-size:18px;">${t("nothing_found")}</div>`;
}

function updateCompendiumSearchUi() {
  const input = $("compendiumSearch");
  const isRulesMode = compendiumSearchMode === "rules";

  if (input) {
    input.placeholder = isRulesMode ? t("compendium_search") : t("model_search_placeholder");
  }

  const modelsBtn = $("compendiumSearchModeModelsBtn");
  const rulesBtn = $("compendiumSearchModeRulesBtn");
  if (modelsBtn) modelsBtn.classList.toggle("active", !isRulesMode);
  if (rulesBtn) rulesBtn.classList.toggle("active", isRulesMode);
}

function renderCompendiumModelsSearch(query = "") {
  const normalizedQuery = String(query).toLowerCase().trim();
  const results = models
    .filter(m => {
      if (!normalizedQuery) return true;

      const factions = Array.isArray(m.faction)
        ? m.faction
        : typeof m.faction === "string"
          ? m.faction.replace(/ *& */gi, ",").replace(/ *\/ */g, ",").split(",").map(s => s.trim())
          : [];

      const rank = Array.isArray(m.rank) ? m.rank.join(" ") : (m.rank || "");
      const factionText = factions.join(" ");

      return [
        m.name,
        rank,
        factionText,
        localizeRank(m.rank || "Free Agent"),
        localizeFactionList(Array.isArray(m.faction) ? m.faction : (m.faction || "—"))
      ].some(value => String(value).toLowerCase().includes(normalizedQuery));
    })
    .sort((a, b) => a.name.localeCompare(b.name));

  const html = results.length ? results.map(m => `
    <div class="comp-entry" style="cursor:pointer" onclick="showFullCard(models[${m._id}])">
      <div class="comp-title" style="background:#222;padding:16px;font-size:18px">
        ${m.name}<span style="float:right;color:#e94560;font-weight:bold">${displayValue(m.rep)} Rep • $${displayValue(m.funding)} • ${getPrintableStatusText(m)}</span>
      </div>
      <div class="comp-text" style="padding:12px;font-size:14px;color:#aaa">
        ${localizeRank(m.rank || "Free Agent")} • ${localizeFactionList(Array.isArray(m.faction) ? m.faction : (m.faction || "—"))}
      </div>
    </div>`).join("") : `<div style="text-align:center;color:#888;padding:80px;font-size:18px;">${t("nothing_found")}</div>`;

  $("compendiumList").innerHTML = html;
}

