// Загрузка сохранённого языка при старте
document.addEventListener('DOMContentLoaded', () => {
  const savedLang = localStorage.getItem('bmg_lang') || 'ru';
  setLanguage(savedLang);
});

const $ = id => document.getElementById(id);

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function escapeAttribute(value) {
  return escapeHtml(value);
}

const THREE_JOKERS_NAMES = [
  "Joker (The Clown)",
  "Joker (The Comedian)",
  "Joker (The Criminal)"
];

function getModelIdentityKey(model) {
  if (!model) return "";
  if (model.id !== undefined && model.id !== null && model.id !== "") return `stable:${model.id}`;
  if (model._id !== undefined && model._id !== null) return `id:${model._id}`;
  return `${model.name || ""}||${model.realname || ""}||${model.base || ""}`;
}

function slugifyModelIdPart(value) {
  const slug = String(value || "model")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return slug || "model";
}

function ensureStableModelIds(modelList) {
  const usedIds = new Set();

  modelList.forEach((model, index) => {
    const baseId = model.id
      ? String(model.id)
      : [
          slugifyModelIdPart(model.name),
          slugifyModelIdPart(model.realname),
          slugifyModelIdPart(model.base)
        ].join("-");

    let candidate = baseId || `model-${index + 1}`;
    let suffix = 2;
    while (usedIds.has(candidate)) {
      candidate = `${baseId}-${suffix++}`;
    }

    model.id = candidate;
    usedIds.add(candidate);
  });
}

function isSameModel(a, b) {
  return getModelIdentityKey(a) !== "" && getModelIdentityKey(a) === getModelIdentityKey(b);
}

function findBaseModel(model) {
  return models.find(m => isSameModel(m, model)) || null;
}

function findCrewModel(model) {
  return crew.find(m => isSameModel(m, model)) || null;
}

const hasInCrew = m => crew.some(x => isSameModel(x, m));
const countInCrew = m => crew.filter(x => isSameModel(x, m)).length;

function isThreeJokersModel(model) {
  return !!model && Array.isArray(model.traits) && model.traits.includes("Three Jokers") && THREE_JOKERS_NAMES.includes(model.name);
}

function hasAnyThreeJokersInCrew() {
  return crew.some(isThreeJokersModel);
}

function hasFullThreeJokersInCrew() {
  return THREE_JOKERS_NAMES.every(name => crew.some(model => model.name === name));
}

function getThreeJokersCrewMember(name = "Joker (The Criminal)") {
  return crew.find(model => model.name === name) || null;
}

function getThreeJokersModels() {
  return THREE_JOKERS_NAMES
    .map(name => models.find(model => model.name === name))
    .filter(Boolean);
}

// ======================== ФУНКЦИИ МЕНЮ ========================
// Улучшенная функция очистки имени от иконок и лишних символов
function getCleanName(name) {
  if (!name) return "";
  // Удаляем всё, что в фигурных скобках {...} и обрезаем пробелы
  // Также заменяем специфические апострофы на стандартные
  return name.split('{')[0].trim().replace(/’/g, "'");
}

function findCompendiumEntry(searchTerm) {
  if (!window.compendium) return null;

  // 1. Очищаем поисковый запрос (например, "Fly {ICON}" -> "Fly")
  const cleanSearch = getCleanName(searchTerm);
  const lowerSearch = cleanSearch.toLowerCase();

  // 2. Пробуем найти точное совпадение (на случай, если ищем "Fast (2'')")
  if (window.compendium[searchTerm]) return window.compendium[searchTerm];
  if (window.compendium[cleanSearch]) return window.compendium[cleanSearch];

  const keys = Object.keys(window.compendium);

  // 3. Поиск с игнорированием регистра и иконок в ключах базы
  for (let key of keys) {
    const cleanKey = getCleanName(key).toLowerCase();
    if (cleanKey === lowerSearch) {
      return window.compendium[key];
    }
  }

  // 4. Логика для трейтов с параметрами в скобках, например "Fast (3)"
  // Если в карточке "Fast (2'')", а в базе "Fast" или "Fast {ICON}"
  if (cleanSearch.includes('(')) {
    const baseName = cleanSearch.split('(')[0].trim().toLowerCase();
    for (let key of keys) {
      const cleanKey = getCleanName(key).split('(')[0].trim().toLowerCase();
      if (cleanKey === baseName) {
        return window.compendium[key];
      }
    }
  }

  return null;
}

// ======================== ПРОВЕРКА ЗАВИСИМОСТЕЙ МОДЕЛЕЙ ========================
// Возвращает true, если зависимость модели выполнена (требуемая модель есть в отряде)
// Также проверяет правила Aversion — если в отряде есть модель из списка Aversion, возвращает false
function checkModelDependency(model) {
  // Проверяем зависимости (Required)
  const dependency = window.modelDependencyRules?.[model.name];
  if (dependency) {
    const requiredModel = dependency.requiredModel;
    if (requiredModel) {
      // Проверяем, есть ли требуемая модель в отряде
      if (!crew.some(m => m.name === requiredModel)) {
        return false;
      }
    }
  }

  // Проверяем правила Aversion
  const aversionList = window.modelAversionRules?.[model.name];
  if (aversionList && Array.isArray(aversionList)) {
    // Если в отряде есть хотя бы одна модель из списка Aversion, эта модель не может быть добавлена
    if (crew.some(m => aversionList.includes(m.name))) {
      return false;
    }
  }

  // Также проверяем обратную ситуацию: если эта модель в отряде,
  // то модели из её списка Aversion не могут быть добавлены
  // Это обрабатывается при фильтрации списка моделей

  return true;
}

// Возвращает имя требуемой модели или null, если зависимости нет или она выполнена
function getUnmetDependency(model) {
  const dependency = window.modelDependencyRules?.[model.name];
  if (!dependency) return null;

  const requiredModel = dependency.requiredModel;
  if (!requiredModel) return null;

  if (!crew.some(m => m.name === requiredModel)) {
    return requiredModel;
  }

  return null;
}

// Проверяет, должна ли модель быть скрыта из-за правил Aversion
// Возвращает true, если модель должна быть скрыта (в отряде есть модель, для которой эта модель в списке Aversion)
function checkAversionHidden(model) {
  // Проверяем каждую модель в отряде: есть ли текущая модель в её списке Aversion
  for (const crewModel of crew) {
    const aversionList = window.modelAversionRules?.[crewModel.name];
    if (aversionList && Array.isArray(aversionList) && aversionList.includes(model.name)) {
      return true; // Эта модель должна быть скрыта
    }
  }
  return false;
}

function loadMyCrewsFromStorage() {
  try {
    const raw = localStorage.getItem(MY_CREWS_STORAGE_KEY);
    if (!raw) {
      myCrews = [];
      return;
    }

    const parsed = JSON.parse(raw);
    myCrews = Array.isArray(parsed) ? parsed.filter(item =>
      item && typeof item.id === "string" && typeof item.text === "string"
    ) : [];
  } catch (error) {
    console.warn("Failed to load My Crews from storage", error);
    myCrews = [];
  }
}

function saveMyCrewsToStorage() {
  try {
    localStorage.setItem(MY_CREWS_STORAGE_KEY, JSON.stringify(myCrews));
  } catch (error) {
    console.warn("Failed to save My Crews to storage", error);
  }
}

function formatMyCrewDate(value) {
  if (!value) return "";
  try {
    return new Date(value).toLocaleString(currentLang === 'ru' ? 'ru-RU' : 'en-US');
  } catch (error) {
    return value;
  }
}

function createMyCrewRecordFromText(text) {
  const normalizedText = String(text || "").replace(/\r\n/g, "\n").trim();
  const parsed = parseRosterImportText(normalizedText);
  const title = parsed.crewName || parsed.entries[0]?.modelName || parsed.faction || "Crew";

  return {
    id: `crew_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    title,
    faction: parsed.faction,
    modelCount: parsed.entries.length,
    addedAt: new Date().toISOString(),
    text: normalizedText
  };
}

function renderMyCrews() {
  const container = $('myCrewsList');
  if (!container) return;

  if (!myCrews.length) {
    container.innerHTML = `<div class="my-crews-empty">${t("my_crews_empty")}</div>`;
    return;
  }

  const sortedCrews = [...myCrews].sort((a, b) => String(b.addedAt || "").localeCompare(String(a.addedAt || "")));

  container.innerHTML = sortedCrews.map(crewEntry => `
    <div class="my-crew-card" data-my-crew-id="${escapeAttribute(crewEntry.id)}">
      <div class="my-crew-card-head">
        <div>
          <div class="my-crew-title">${escapeHtml(crewEntry.title || crewEntry.faction || "Crew")}</div>
          <div class="my-crew-subtitle">${t("my_crews_faction")}: ${escapeHtml(crewEntry.faction || "Unknown")}</div>
        </div>
        <div class="my-crew-meta">
          <div>${escapeHtml(String(crewEntry.modelCount || 0))} ${t("my_crews_models")}</div>
          <div>${t("my_crews_added")}: ${escapeHtml(formatMyCrewDate(crewEntry.addedAt))}</div>
        </div>
      </div>
      <pre class="my-crew-preview">${escapeHtml(crewEntry.text.split("\n").slice(0, 6).join("\n"))}</pre>
      <div class="my-crew-actions">
        <button class="my-crew-action-btn" data-my-crew-open="${escapeAttribute(crewEntry.id)}">${t("my_crews_open")}</button>
        <button class="my-crew-action-btn" data-my-crew-download="${escapeAttribute(crewEntry.id)}">${t("my_crews_download")}</button>
        <button class="my-crew-action-btn danger" data-my-crew-delete="${escapeAttribute(crewEntry.id)}">${t("my_crews_delete")}</button>
      </div>
    </div>
  `).join("");

  container.querySelectorAll('[data-my-crew-open]').forEach(button => {
    button.addEventListener('click', () => openSavedMyCrew(button.dataset.myCrewOpen));
  });
  container.querySelectorAll('[data-my-crew-download]').forEach(button => {
    button.addEventListener('click', () => downloadSavedMyCrew(button.dataset.myCrewDownload));
  });
  container.querySelectorAll('[data-my-crew-delete]').forEach(button => {
    button.addEventListener('click', () => deleteSavedMyCrew(button.dataset.myCrewDelete));
  });
}

