function openSavedMyCrew(crewId) {
  const crewEntry = myCrews.find(item => item.id === crewId);
  if (!crewEntry) return;

  try {
    importRosterFromText(crewEntry.text);
  } catch (error) {
    alert(error.message || (currentLang === "ru" ? "Не удалось открыть сохранённую банду." : "Failed to open saved crew."));
  }
}

function downloadTextFile(fileName, text) {
  const blob = new Blob([text], { type: "text/plain;charset=utf-8" });
  const downloadUrl = URL.createObjectURL(blob);
  const link = document.createElement("a");

  link.href = downloadUrl;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);

  setTimeout(() => URL.revokeObjectURL(downloadUrl), 0);
}

function downloadSavedMyCrew(crewId) {
  const crewEntry = myCrews.find(item => item.id === crewId);
  if (!crewEntry) return;

  const safeName = String(crewEntry.title || crewEntry.faction || "crew")
    .replace(/[<>:"/\\|?*]+/g, "_")
    .replace(/\s+/g, "_");

  downloadTextFile(`bmg_saved_${safeName}.txt`, crewEntry.text);
}

function deleteSavedMyCrew(crewId) {
  const crewEntry = myCrews.find(item => item.id === crewId);
  if (!crewEntry) return;
  if (!confirm(t("my_crews_delete_confirm"))) return;

  myCrews = myCrews.filter(item => item.id !== crewId);
  saveMyCrewsToStorage();
  renderMyCrews();
}

function promptMyCrewTxtFile() {
  const input = document.createElement("input");
  input.type = "file";
  input.accept = ".txt,text/plain";
  input.onchange = event => {
    const file = event.target.files && event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = () => {
      try {
        const record = createMyCrewRecordFromText(reader.result || "");
        const duplicate = myCrews.some(item => item.text.trim() === record.text.trim());
        if (duplicate) {
          alert(t("my_crews_import_duplicate"));
          return;
        }

        myCrews.unshift(record);
        saveMyCrewsToStorage();
        renderMyCrews();
        alert(t("my_crews_import_success"));
      } catch (error) {
        alert(error.message || t("my_crews_import_failed"));
      }
    };
    reader.onerror = () => {
      alert(currentLang === "ru" ? "Не удалось прочитать файл." : "Failed to read file.");
    };
    reader.readAsText(file, "utf-8");
  };
  input.click();
}

function importMyCrewFromTxt() {
  loadMyCrewsFromStorage();
  promptMyCrewTxtFile();
}

function buildAllMyCrewsExportText() {
  const lines = [
    "BMG MY CREWS",
    `Generated: ${new Date().toISOString()}`,
    `Count: ${myCrews.length}`,
    "════════════════════════════════════════"
  ];

  myCrews.forEach((crewEntry, index) => {
    lines.push("");
    lines.push(`### CREW ${index + 1}`);
    lines.push(`Title: ${crewEntry.title || crewEntry.faction || "Crew"}`);
    lines.push(`Faction: ${crewEntry.faction || "Unknown"}`);
    lines.push(`Added: ${crewEntry.addedAt || ""}`);
    lines.push("────────────────────────────────────────");
    lines.push(String(crewEntry.text || "").trim());
    lines.push("════════════════════════════════════════");
  });

  return lines.join("\n");
}

function exportAllMyCrewsTxt() {
  loadMyCrewsFromStorage();
  if (!myCrews.length) {
    alert(t("my_crews_export_empty"));
    return;
  }

  downloadTextFile("bmg_my_crews.txt", buildAllMyCrewsExportText());
  alert(t("my_crews_export_done"));
}

